142	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
143	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
144	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
145	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
146	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
147	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
148	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
152	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
153	            ownerDto.getMembershipLevel());
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
