180	    /**
181	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
182	     * given business day as their {@code registrationDate}. The count is keyed by the
183	     * business-day-adjusted registration date of the owner being created (see
184	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
185	     * with no {@code registrationDate} are ignored.
186	     *
187	     * @param registrationDate the business-day-adjusted registration date of the owner being created
188	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
189	     */
190	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
191	        long count = this.clinicService.findAllOwners().stream()
192	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
193	            .count();
194	        if (count >= DAILY_OWNER_LIMIT) {
195	            throw new DailyOwnerLimitException(registrationDate);
