199	    /**
200	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
201	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
202	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
203	     */
204	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
