206	    /**
207	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
208	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
209	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
210	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
211	     * owner being created is excluded (it has not yet been saved).
212	     *
213	     * @param registrationDate the business-day-adjusted registration date of the owner being created
214	     * @return {@code true} if more than the threshold of owners already carry this business day
215	     */
216	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
217	        long count = this.clinicService.findAllOwners().stream()
218	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
219	            .count();
220	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
