223	    /**
224	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
225	     * the following Monday; a weekday is returned unchanged. This applies to the effective
226	     * registration date whether it was supplied in the request or defaulted to the server date, and
227	     * every value derived from the registration date uses the adjusted result.
228	     *
229	     * @param date the effective registration date
230	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
231	     */
232	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
233	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
234	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
235	            date = date.plusDays(1);
236	        }
237	        return date;
238	    }
