265	    /**
266	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
267	     * REGION is the owner's canonical region (derived by preferring the postcode, see
268	     * {@link Localities#region(String, String)} — the same region derivation shared with the
269	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
270	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
271	     * There are no sequence numbers: the code is fully derived from the owner's own identity fields.
272	     *
273	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
274	     * @param telephone the owner's normalized (E.164) telephone
275	     * @param lastName the owner's last name
276	     * @return the assigned customer code
277	     */
278	    private String assignCustomerCode(String region, String telephone, String lastName) {
279	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
280	        String hash8 = sha256UpperHex(basis).substring(0, 8);
281	        return region + "-" + hash8;
282	    }
283	
284	    /**
285	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
286	     */
287	    private static String sha256UpperHex(String value) {
288	        try {
289	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
290	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
291	            StringBuilder sb = new StringBuilder(digest.length * 2);
292	            for (byte b : digest) {
293	                sb.append(String.format("%02X", b));
294	            }
295	            return sb.toString();
296	        }
297	        catch (java.security.NoSuchAlgorithmException e) {
298	            throw new IllegalStateException("SHA-256 not available", e);
299	        }
300	    }
