348	     * @param owner the owner being created, with its last name and postcode already set
349	     * @param sharesHousehold whether the request opted in via {@code sharesHousehold}
350	     * @throws DuplicateHouseholdException (409 Conflict) if the owner joins an existing household and did
351	     *         not opt in
352	     */
353	    private void rejectDuplicateHousehold(Owner owner, boolean sharesHousehold) {
354	        if (sharesHousehold) {
355	            return;
356	        }
357	        String postcode = owner.getPostcode();
358	        if (postcode == null) {
359	            return;
360	        }
361	        String householdId = Households.householdId(owner.getLastName(), postcode);
362	        boolean exists = this.clinicService.findAllOwners().stream()
363	            .anyMatch(existing -> householdId.equals(
364	                Households.householdId(existing.getLastName(), existing.getPostcode())));
365	        if (exists) {
366	            throw new DuplicateHouseholdException(owner.getLastName(), postcode);
367	        }
