370	    /**
371	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
372	     * sharing this owner's last name (compared case-insensitively) and postcode (an exact match of the
373	     * stored 4-digit value) while carrying a <em>different</em> telephone. A soft match is distinct from
374	     * the hard duplicate rejected earlier by {@link #rejectDuplicateIdentity}: the owner is still
375	     * created, but flagged. When more than one existing owner matches, the earliest (lowest id) is
376	     * returned so the reference is deterministic. An owner with no postcode can never soft-match.
377	     *
378	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
379	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
380	     */
381	    private Integer findPossibleDuplicateOf(Owner owner) {
382	        String postcode = owner.getPostcode();
383	        if (postcode == null) {
384	            return null;
385	        }
386	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
387	        String telephone = owner.getTelephone();
388	        return this.clinicService.findAllOwners().stream()
389	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
390	            .filter(existing -> postcode.equals(existing.getPostcode()))
391	            .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
392	            .map(Owner::getId)
393	            .filter(java.util.Objects::nonNull)
394	            .min(java.util.Comparator.naturalOrder())
395	            .orElse(null);
396	    }
