398	    /**
399	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
400	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
401	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
402	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
403	     * {@code "+61412345678"}. The E.164 value is stored and returned.
404	     * <p>
405	     * The national-number length (the digits after the country code) is additionally validated for
406	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
407	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
408	     *
409	     * @param telephone the raw telephone as submitted
410	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
411	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
412	     *         or its national-number length is wrong for its country code
413	     */
414	    private String normalizeTelephone(String telephone) {
415	        String raw = telephone == null ? "" : telephone.trim();
416	        boolean hasCountryCode = raw.startsWith("+");
417	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
418	        if (hasCountryCode) {
419	            cleaned = cleaned.substring(1);
420	        }
421	        String digits;
422	        if (hasCountryCode) {
423	            digits = cleaned;
424	        } else {
425	            if (cleaned.startsWith("0")) {
426	                cleaned = cleaned.substring(1);
427	            }
428	            digits = "61" + cleaned;
429	        }
430	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
431	            throw new InvalidTelephoneException(telephone);
432	        }
433	        return "+" + digits;
434	    }
435	
436	    /**
437	     * Checks the national-number length of an E.164 digit string against its country code for the
438	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
439	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
440	     *
441	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
442	     * @return {@code true} if the national-number length is acceptable for the country code
443	     */
444	    private boolean hasValidNationalLength(String digits) {
445	        if (digits.startsWith("61")) {
446	            return digits.length() - 2 == 9;
447	        }
448	        if (digits.startsWith("1")) {
449	            return digits.length() - 1 == 10;
450	        }
451	        return true;
452	    }
