454	    /**
455	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
456	     * multi-character top-level label. Deliberately lenient about the exact character set while still
457	     * rejecting values that are clearly not addresses (e.g. missing '@').
458	     */
459	    private static final java.util.regex.Pattern EMAIL_PATTERN =
460	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
461	
462	    /**
463	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
464	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
465	     * lower-cased before being stored and returned.
466	     *
467	     * @param email the raw email as submitted, may be {@code null}
468	     * @return the lower-cased email, or {@code null} when none was supplied
469	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
470	     */
471	    private String normalizeEmail(String email) {
472	        if (email == null || email.isBlank()) {
473	            return null;
474	        }
475	        String trimmed = email.trim();
476	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
477	            throw new InvalidEmailException(email);
478	        }
479	        return trimmed.toLowerCase(java.util.Locale.ROOT);
480	    }
