482	    /**
483	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
484	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
485	     * {@link Localities#region}) accepts any 4-digit postcode.
486	     */
487	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
488	        "NSW", new int[] {2000, 2099},
489	        "VIC", new int[] {3000, 3099},
490	        "QLD", new int[] {4000, 4099});
491	
492	    /**
493	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
494	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
495	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
496	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
497	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
498	     *
499	     * @param city the owner's city, used to derive the region whose range constrains the postcode
500	     * @param postcode the raw postcode as submitted, may be {@code null}
501	     * @return the postcode when supplied, or {@code null} when none was supplied
502	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
503	     *         out of range for the city's region
504	     */
505	    private String validatePostcode(String city, String postcode) {
506	        if (postcode == null || postcode.isBlank()) {
507	            return null;
508	        }
509	        if (!postcode.matches("[0-9]{4}")) {
510	            throw new InvalidPostcodeException(postcode);
511	        }
512	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
513	        if (range != null) {
514	            int value = Integer.parseInt(postcode);
515	            if (value < range[0] || value > range[1]) {
516	                throw new InvalidPostcodeException(postcode);
517	            }
518	        }
519	        return postcode;
520	    }
521	
522	    /**
523	     * Common street-type abbreviations expanded to their full word during address normalization.
524	     */
525	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
526	        "ST", "STREET",
527	        "RD", "ROAD",
528	        "AVE", "AVENUE");
529	
530	    /**
531	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
532	     * whitespace collapse to a single space, the value is upper-cased and common street-type
533	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
534	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
535	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
536	     * for every address comparison (household duplicate detection and the shared household id).
537	     *
538	     * @param address the raw address as submitted
539	     * @return the normalized address
540	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
541	     */
542	    private String normalizeAddress(String address) {
543	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
544	        if (collapsed.isEmpty()) {
545	            throw new InvalidAddressException(address);
546	        }
547	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
548	        StringBuilder normalized = new StringBuilder(collapsed.length());
549	        for (int i = 0; i < tokens.length; i++) {
550	            if (i > 0) {
551	                normalized.append(' ');
552	            }
553	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
554	        }
555	        return normalized.toString();
556	    }
