558	    /**
559	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
560	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
561	     * owners are duplicates when they share the same normalized telephone and the same normalized email
562	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
563	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
564	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
565	     * still match.
566	     * <p>
567	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
568	     * grouping, so two members of the same household with different telephones have different
569	     * identities and are both allowed. Only owners with the same telephone and email collide.
570	     *
571	     * @param owner the owner being created, with its telephone and email already normalized
572	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
573	     */
574	    private void rejectDuplicateIdentity(Owner owner) {
575	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
576	        boolean duplicate = this.clinicService.findAllOwners().stream()
577	            .anyMatch(existing -> identity.equals(
578	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
579	        if (duplicate) {
580	            String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
581	            throw new DuplicateIdentityException(
582	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
583	        }
584	    }
585	
586	    /**
587	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
588	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
589	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
590	     */
591	    private String personalIdentity(String telephone, String email) {
592	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
593	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
594	    }
595	
596	    /**
597	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
598	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
599	     * when its national-number length does not match its country code.
600	     */
601	    private String toE164OrNull(String telephone) {
602	        try {
603	            return normalizeTelephone(telephone);
604	        } catch (InvalidTelephoneException e) {
605	            return null;
606	        }
607	    }
